adcs_vec3_t u;
double field_norm, req_norm, dot_product, perp_norm;
adcs_status_t status;

/* Check for NULL pointers */
if (request == NULL || field == NULL || parallel == NULL || 
    perpendicular == NULL || fraction == NULL) {
    return ADCS_E_NULL;
}

/* Initialize outputs to zero in case of early failure */
parallel->x = 0.0; parallel->y = 0.0; parallel->z = 0.0;
perpendicular->x = 0.0; perpendicular->y = 0.0; perpendicular->z = 0.0;
*fraction = 0.0;

/* Check for non-finite values in request and field */
if (!adcs_is_finite_vec3(request) || !adcs_is_finite_vec3(field)) {
    return ADCS_E_NOT_FINITE;
}

/* Compute norm of field */
field_norm = adcs_vec3_norm(field);

/* Check for degenerate field (norm <= ADCS_EPS_NORM) */
if (field_norm <= ADCS_EPS_NORM) {
    return ADCS_E_DEGENERATE;
}

/* Normalize field to get u */
status = adcs_vec3_normalize(field, ADCS_EPS_NORM, &u);
if (status != ADCS_OK) {
    return ADCS_E_DEGENERATE;
}

/* Compute parallel component: (request . u) * u */
dot_product = adcs_vec3_dot(request, &u);
*parallel = adcs_vec3_scale(&u, dot_product);

/* Compute perpendicular component: request - parallel */
*perpendicular = adcs_vec3_sub(request, parallel);

/* Compute controllable fraction */
req_norm = adcs_vec3_norm(request);

if (req_norm <= ADCS_EPS_NORM) {
    /* Zero request -> fraction is 0 */
    *fraction = 0.0;
} else {
    perp_norm = adcs_vec3_norm(perpendicular);
    *fraction = perp_norm / req_norm;
}

return ADCS_OK;

