if ((request == NULL) || (field == NULL) || (parallel == NULL) || 
    (perpendicular == NULL) || (fraction == NULL)) {
    return ADCS_E_NULL;
}

if (!adcs_is_finite_vec3(request) || !adcs_is_finite_vec3(field)) {
    return ADCS_E_DEGENERATE;
}

double field_norm = adcs_vec3_norm(field);
if (field_norm <= ADCS_EPS_NORM) {
    *parallel = (adcs_vec3_t){0.0, 0.0, 0.0};
    *perpendicular = (adcs_vec3_t){0.0, 0.0, 0.0};
    *fraction = 0.0;
    return ADCS_E_DEGENERATE;
}

adcs_vec3_t u;
double inv_field_norm = 1.0 / field_norm;
u.x = field->x * inv_field_norm;
u.y = field->y * inv_field_norm;
u.z = field->z * inv_field_norm;

double dot_prod = adcs_vec3_dot(request, &u);
adcs_vec3_t parallel_vec = adcs_vec3_scale(&u, dot_prod);
*parallel = parallel_vec;

adcs_vec3_t perp_vec = adcs_vec3_sub(request, &parallel_vec);
*perpendicular = perp_vec;

double request_norm = adcs_vec3_norm(request);
if (request_norm <= ADCS_EPS_NORM) {
    *fraction = 0.0;
} else {
    double perp_norm = adcs_vec3_norm(&perp_vec);
    *fraction = perp_norm / request_norm;
}

return ADCS_OK;

